-- 631: Original BrillaPrep flashcards, batch flashcard-decks-sprint3-001, part 3 of 3.
-- Curriculum-aligned revision content; not official WAEC or NaCCA material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_01', 'deck_sys_topic_thermodynamics', 'Distinguish between heat and temperature.', 'Heat is the thermal energy transferred from a hotter body to a colder one, measured in joules; temperature is the degree of hotness — a measure of the average kinetic energy of the particles — measured in kelvin or degrees Celsius.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_02', 'deck_sys_topic_thermodynamics', 'Define the specific heat capacity of a substance and write the heat equation that uses it.', 'The heat energy required to raise the temperature of 1 kg of the substance by 1 °C (1 K). The heat equation is Q = mcΔθ, where m is the mass and Δθ the temperature change.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_03', 'deck_sys_topic_thermodynamics', 'State the SI unit of specific heat capacity, and give the value for water.', 'Joules per kilogram per kelvin, J/(kg·K) (equivalently J/(kg·°C)); for water c ≈ 4200 J/(kg·°C) — an unusually high value, which is why water heats up and cools down slowly.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_04', 'deck_sys_topic_thermodynamics', 'Define the specific latent heat of fusion.', 'The heat energy required to change 1 kg of a substance from solid to liquid at its melting point, without any change of temperature. The heat involved is Q = ml, where l is the specific latent heat.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_05', 'deck_sys_topic_thermodynamics', 'Why does the temperature of a pure substance stay constant while it is melting or boiling?', 'The heat supplied is used to break the bonds between particles — increasing their potential energy — rather than to raise their average kinetic energy, which determines temperature. This hidden heat is the latent heat.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_06', 'deck_sys_topic_thermodynamics', 'Which is larger for a given substance, the specific latent heat of vaporisation or of fusion, and why?', 'The latent heat of vaporisation is larger, because separating the molecules completely into the gas phase takes far more energy than merely loosening them into the liquid state (for water, about 2.26 × 10⁶ J/kg against 3.34 × 10⁵ J/kg).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_07', 'deck_sys_topic_thermodynamics', 'Describe conduction of heat, and name a good conductor and a poor conductor.', 'Heat transfer through a material without any movement of the material itself, by the vibration of particles and — in metals — the movement of free electrons; copper is a good conductor, wood (or air) a poor conductor (an insulator).', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_08', 'deck_sys_topic_thermodynamics', 'Explain convection and state where it can occur.', 'Heat transfer by the bulk movement of a fluid: heated fluid expands, becomes less dense and rises, while cooler, denser fluid sinks to replace it, setting up a convection current. It occurs only in liquids and gases.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_09', 'deck_sys_topic_thermodynamics', 'What is thermal radiation, and which surfaces emit and absorb it best?', 'Heat transfer by infra-red electromagnetic waves, which needs no medium and can cross a vacuum; dull black surfaces are the best emitters and absorbers, while shiny silvery surfaces are the poorest.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_10', 'deck_sys_topic_thermodynamics', 'Distinguish between evaporation and boiling.', 'Evaporation occurs at all temperatures, only at the liquid surface, and causes cooling; boiling occurs throughout the liquid at one fixed temperature — the boiling point — when the vapour pressure equals the external pressure.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_11', 'deck_sys_topic_thermodynamics', 'Calculate the heat needed to raise the temperature of 2 kg of water by 15 °C. (c = 4200 J/(kg·°C))', 'Q = mcΔθ = 2 × 4200 × 15 = 126,000 J = 126 kJ.', NULL, 'Use Q = mcΔθ: mass × specific heat capacity × temperature rise.', 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_thermodynamics_12', 'deck_sys_topic_thermodynamics', 'Calculate the heat released when 0.5 kg of steam at 100 °C condenses to water at the same temperature. (l = 2.26 × 10⁶ J/kg)', 'Q = ml = 0.5 × 2.26 × 10⁶ = 1.13 × 10⁶ J = 1.13 MJ.', NULL, 'Latent heat only: Q = ml; the temperature does not change.', 3);
